{
  "contract": "SafePaymentVault",
  "closure": {
    "site_function": "Withdraw",
    "site_call": ".call",
    "functions": [
      "Withdraw",
      "GetTotalBalance",
      "MakeDeposit"
    ],
    "justification": "All functions that read or write exposed storage variables TotalBalance and _ethBal are included."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "GetTotalBalance",
      "MakeDeposit"
    ],
    "nesting_bound": {
      "Withdraw": 1
    }
  },
  "phases": {
    "function": "Withdraw",
    "pre": {
      "name": "pre",
      "from_marker": "entry",
      "to_marker": "before .call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before .call",
      "to_marker": "after .call"
    },
    "post": {
      "name": "post",
      "from_marker": "after .call",
      "to_marker": "exit"
    },
    "linearization_point": "after .call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "The amount of balance in flight during the external call.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_ethBal == TotalBalance + inFlight",
    "stable_formula": "_ethBal == TotalBalance",
    "kind": "additive"
  },
  "composition": {
    "target_property": "TotalBalance == _ethBal",
    "rule": "The exposure invariant ensures that the balance remains consistent during reentrant calls."
  }
}
